 assert!(owner.with_local_cover(context(),"11111111-1111-4111-8111-111111111111".into(),|_|Ok(())).await.is_err());assert_eq!(fs::read(&path).unwrap(),[3,2,1]);fs::remove_dir_all(root).unwrap();
