#[tokio::test]async fn bounded_large_canonical_source_does_not_require_ambient_sqlite_temp_files(){
 let(root,_owner,mut request)=fixture("large-source").await;request.byte_length=3;
 let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(root.join(".starlane/starlane-notes.sqlite3"))).await.unwrap();let mut snapshot=crate::local_database::read_snapshot_from_pool(&pool,"none").await.unwrap().unwrap();let body="original published content ".repeat(60000);snapshot["documents"][0]["content"]=json!(body);snapshot["drafts"][0]["content"]=snapshot["documents"][0]["content"].clone();snapshot["documents"].as_array_mut().unwrap().push(json!({"id":"other-page","space_id":"space","title":"Other source page","content":"smaller"}));
 snapshot["search_index"]=json!([{"document_id":"page","space_id":"space","title":"Original page","updated_at":"original","content":body},{"document_id":"other-page","space_id":"space","title":"Other source page","updated_at":"original","content":body}]);
 snapshot["sync_state"]["queued_operations"]=json!([{"id":"original-operation","entity_type":"document","entity_id":"page","action":"update_content","queued_at":"original","attempts":0,"payload":{"content":body}}]);
 let mut tx=pool.begin().await.unwrap();let revision=crate::local_database::write_snapshot_in_tx(&mut tx,"none",&snapshot).await.unwrap();tx.commit().await.unwrap();pool.close().await;
 let selection=vault::SnapshotRequestBinding::capture_at(root.with_extension("settings.json"),root.clone(),"none").unwrap();let owner=Owner::capture(selection,"none",&revision,context()).unwrap();request.original_binding=owner.binding();let c=owner.prepare_local_cover(context(),request).await.unwrap();let(c,_)=c.append_owned(context(),0,vec![1,2,3]).await.unwrap();let result=c.finish(context()).await.unwrap();
 let expected_search=json!([snapshot["search_index"][1],snapshot["search_index"][0]]);
 assert!(result["canonical_snapshot"]["search_index"]==expected_search,"Search payload bytes or SQLite key ordering changed");
 assert!(result["canonical_snapshot"]["sync_state"]["queued_operations"]==snapshot["sync_state"]["queued_operations"],"Original queue payload/order changed");
 let selection=vault::SnapshotRequestBinding::capture_at(root.with_extension("settings.json"),root.clone(),"none").unwrap();let owner=Owner::capture(selection,"none",result["canonical_snapshot"]["canonical_revision"].as_str().unwrap(),context()).unwrap();owner.with_local_cover(context(),"11111111-1111-4111-8111-111111111111".into(),|r|{let mut bytes=Vec::new();r.copy_exact(&mut bytes)?;assert_eq!(bytes,[1,2,3]);Ok(())}).await.unwrap();fs::remove_dir_all(root).unwrap();
}

