#[tokio::test]
async fn complete_archive_uses_held_original_local_reader_and_distinct_provenance() {
 let _serial=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());
 let(root,owner,result)=completed("archive-local-original").await;
 let destination=root.with_extension("zip");let selected_destination=destination.clone();
 let report=owner.with_capture(context(),move|capture|{
  assert_eq!(capture.raw_local_covers.len(),1);assert!(capture.raw_receipts.is_empty());
  let selected=crate::local_database::attachment_download_owner::native_archive_output::test_selection(selected_destination,capture.output_binding())?;
  let binding=capture.output_binding();crate::local_database::attachment_download_owner::native_archive_output::compose(capture,selected,||Ok(binding.clone()))
 }).await.unwrap();
 let mut zip=zip::ZipArchive::new(fs::File::open(&destination).unwrap()).unwrap();
 let mut manifest=String::new();std::io::Read::read_to_string(&mut zip.by_name("starlane-native/manifest.json").unwrap(),&mut manifest).unwrap();let manifest:Value=serde_json::from_str(&manifest).unwrap();
 assert_eq!(manifest["format"],3);assert_eq!(manifest["binaries"][0]["kind"],"original_local_cover");assert_eq!(manifest["binaries"][0]["asset"],result["asset"]);
 let mut bytes=Vec::new();std::io::Read::read_to_end(&mut zip.by_name(manifest["binaries"][0]["entry"].as_str().unwrap()).unwrap(),&mut bytes).unwrap();assert_eq!(bytes,[1,2,3]);drop(zip);
 let imported_destination=root.with_extension("imported").join("assets");
 let inspection=vault::archive_admission::prepare("none",&destination,&imported_destination).unwrap();assert!(!imported_destination.exists());vault::archive_admission::cancel("none",&inspection.handle).unwrap();
 let stage=destination.parent().unwrap().join(format!(".starlane-archive-{}",report["operation"].as_str().unwrap()));fs::remove_file(destination).unwrap();fs::remove_dir_all(stage).unwrap();fs::remove_dir_all(root).unwrap();
}

