 let publication=owner.with_capture(context(),move|capture|{let binding=capture.output_binding();let selected=crate::local_database::attachment_download_owner::native_archive_output::test_selection(selected_destination,binding.clone())?;crate::local_database::attachment_download_owner::native_archive_output::compose(capture,selected,||Ok(binding.clone()))}).await.unwrap();
 let imported=root.with_extension("new-owner");let(selection,request,result)=crate::local_database::joint_archive::tests::import_existing_owner_archive(&destination,imported.clone(),true).await;
 let installed=PathBuf::from(result["candidate"]["assets"][0]["vault_path"].as_str().unwrap());assert!(vault::delete_vault_asset_file(&imported,&installed).is_err());assert_eq!(fs::read(&installed).unwrap(),[1,2,3]);
 assert_eq!(result["candidate"]["assets"][0]["native_local_version_provenance"],original["asset"]["native_local_version_provenance"]);assert_ne!(result["candidate"]["assets"][0]["vault_path"],original["asset"]["vault_path"]);assert!(!imported.join(".starlane/local-cover-producers").exists());assert!(result["imported_provenance"]["local_covers_json"].is_string());
 let reader=crate::local_database::attachment_download_owner::native_archive_import::Owner::capture(selection.clone(),"none",request,context()).unwrap();reader.with_read(context(),|r|{let mut bytes=Vec::new();r.copy_exact(&mut bytes)?;assert_eq!(bytes,[1,2,3]);Ok(())}).await.unwrap();
 let binding=json!({"context":context(),"root":imported,"revision":result["canonical_revision"]});let asset=&result["candidate"]["assets"][0];let selected_cover=json!({"space_id":"space","document_id":"page","asset_id":asset["id"],"draft_id":"draft","cover_reference":asset["url"]});
