 for field in ["draft_id","cover_reference","document_id","space_id","asset_id"]{let mut wrong=selected_cover.clone();wrong[field]=json!("foreign");assert!(crate::local_database::attachment_download_owner::native_archive_context::cover::test_stream(selection.clone(),context(),context(),binding.clone(),wrong).await.is_err());}
 let mut wrong=context();wrong["sessionId"]=json!("foreign");assert!(crate::local_database::attachment_download_owner::native_archive_context::cover::test_stream(selection.clone(),context(),wrong,binding.clone(),selected_cover.clone()).await.is_err());
 let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(imported.join(".starlane/starlane-notes.sqlite3"))).await.unwrap();let original_draft:String=sqlx::query_scalar("SELECT payload FROM local_vault_records WHERE collection='drafts' AND id='draft'").fetch_one(&pool).await.unwrap();sqlx::query("UPDATE local_vault_records SET payload=json_set(payload,'$.cover_image','foreign') WHERE collection='drafts' AND id='draft'").execute(&pool).await.unwrap();pool.close().await;
