 let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(imported.join(".starlane/starlane-notes.sqlite3"))).await.unwrap();sqlx::query("UPDATE local_vault_records SET payload=?1 WHERE collection='drafts' AND id='draft'").bind(original_draft).execute(&pool).await.unwrap();pool.close().await;
 // Copied source receipts cannot recreate original local creator authority.
 let local=Owner::capture(selection.clone(),"none",result["canonical_revision"].as_str().unwrap(),context()).unwrap();assert!(local.clone().with_local_cover(context(),"11111111-1111-4111-8111-111111111111".into(),|_|Ok(())).await.is_err());
