 let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(root.join(".starlane/starlane-notes.sqlite3"))).await.unwrap();let mut snapshot=crate::local_database::read_snapshot_from_pool(&pool,"none").await.unwrap().unwrap();snapshot["drafts"][0]["cover_image"]=second["asset"]["url"].clone();let mut tx=pool.begin().await.unwrap();let revision=crate::local_database::write_snapshot_in_tx(&mut tx,"none",&snapshot).await.unwrap();tx.commit().await.unwrap();pool.close().await;
 let selection=vault::SnapshotRequestBinding::capture_at(root.with_extension("settings.json"),root.clone(),"none").unwrap();let owner=Owner::capture(selection,"none",&revision,context()).unwrap();let source=root.with_extension("retained.zip");let path=source.clone();let published=owner.with_capture(context(),move|capture|{assert_eq!(capture.raw_local_covers.len(),2);assert_eq!(capture.binaries.len(),2);let binding=capture.output_binding();let selected=crate::local_database::attachment_download_owner::native_archive_output::test_selection(path,binding.clone())?;crate::local_database::attachment_download_owner::native_archive_output::compose(capture,selected,||Ok(binding.clone()))}).await.unwrap();
 let destination=root.with_extension("retained-new-owner");let(selection,old_request,result)=crate::local_database::joint_archive::tests::import_existing_owner_archive(&source,destination.clone(),false).await;assert_eq!(result["candidate"]["assets"].as_array().unwrap().len(),2);
 let old=crate::local_database::attachment_download_owner::native_archive_import::Owner::capture(selection.clone(),"none",old_request.clone(),context()).unwrap();assert!(old.with_read(context(),|r|{let mut bytes=Vec::new();r.copy_exact(&mut bytes)?;Ok(())}).await.is_err(),"Retained history must not acquire a fabricated current serving reference");
 let assets=result["candidate"]["assets"].as_array().unwrap();let index=assets.iter().position(|a|a["id"]==second["asset"]["id"]).unwrap();let asset=&assets[index];assert_eq!(assets.iter().find(|a|a["id"]==first["asset"]["id"]).unwrap()["native_local_version_provenance"],first["asset"]["native_local_version_provenance"]);
 let new_request=crate::local_database::attachment_download_owner::native_archive_import::Request{operation:old_request.operation,request_fingerprint:old_request.request_fingerprint,asset_id:asset["id"].as_str().unwrap().into(),index,space_id:"space".into(),document_id:"page".into()};
 fs::remove_dir_all(&root).unwrap();let current=crate::local_database::attachment_download_owner::native_archive_import::Owner::capture(selection.clone(),"none",new_request,context()).unwrap();current.with_read(context(),|r|{let mut bytes=Vec::new();r.copy_exact(&mut bytes)?;assert_eq!(bytes,[9,8,7]);Ok(())}).await.unwrap();
 let owner=Owner::capture(selection,"none",result["canonical_revision"].as_str().unwrap(),context()).unwrap();let archive=root.with_extension("retained-reexport.zip");let path=archive.clone();let reexport=owner.with_capture(context(),move|capture|{assert_eq!(capture.binaries.len(),2);assert!(capture.raw_local_covers.is_empty());assert_eq!(capture.raw_imports.len(),1);let binding=capture.output_binding();let selected=crate::local_database::attachment_download_owner::native_archive_output::test_selection(path,binding.clone())?;crate::local_database::attachment_download_owner::native_archive_output::compose(capture,selected,||Ok(binding.clone()))}).await.unwrap();
